class Solution {
public:
    int countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int p = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) { p = i; break; }
        }
        for (int i = 0; i < n; i++) {
            if (nums[i] > k) nums[i] = 1;
            else if (nums[i] < k) nums[i] = -1;
            else nums[i] = 0;
        }
        unordered_map<int,int> cnt;
        cnt.reserve(n + 1);
        int pref = 0;
        cnt[0] = 1;
        for (int i = 0; i < p; i++) {
            pref += nums[i];
            cnt[pref]++;
        }
        long long ans = 0;
        for (int r = p; r < n; r++) {
            pref += nums[r];
            ans += cnt[pref];
            ans += cnt[pref - 1];
        }
        return (int)ans;
    }
};
